import type { Schedule, ScheduleDefinition, Schedules } from './types';
/**
 * A `vercel.json` schedule without its name, which is its key in `schedules`.
 * `entrypoint` targets are resolved to `function` before the schedule reaches
 * Build Output.
 */
export type VercelJsonScheduleDefinition = ScheduleDefinition | (Pick<ScheduleDefinition, 'schedule' | 'timezone' | 'jitter'> & {
    entrypoint: string;
    /** Command for a Dockerfile or Containerfile schedule entrypoint. */
    command?: string[];
    /** Directory of a command schedule's service; `entrypoint` is relative to it. */
    root?: string;
});
/** `vercel.json#schedules`: schedules keyed by name. */
export type VercelJsonSchedules = Record<string, VercelJsonScheduleDefinition>;
/** A `vercel.json` schedule with its name. */
export type VercelJsonSchedule = {
    name: string;
} & VercelJsonScheduleDefinition;
/**
 * The schedules in `schedules` with their names, in key order. Accepts the
 * deprecated array format, which already names each schedule.
 */
export declare function getNamedSchedules(schedules: Schedules | readonly Schedule[] | undefined): Schedule[];
export declare function getNamedSchedules(schedules: VercelJsonSchedules | readonly VercelJsonSchedule[] | undefined): VercelJsonSchedule[];
/** Named schedules keyed by name, for `schedules` in Build Output. */
export declare function toScheduleRecord(schedules: readonly Schedule[]): Schedules;
export declare function toScheduleRecord(schedules: readonly VercelJsonSchedule[]): VercelJsonSchedules;
/** Warning for `schedules` in the deprecated array format. */
export declare function getSchedulesArrayDeprecationWarning(source: string): string;
